package com.hyperathlete.app.domain.nutrition

import com.hyperathlete.app.domain.model.AppLanguage
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json
import kotlin.math.abs
import kotlin.math.roundToInt

/*
 * The built-in food list (brief §11), stored as assets/food/foods.json and generated by tools/gen_foods.py.
 * Values are per 100 g; every food has realistic serving units with their weight in grams.
 */

/** Energy and macros. Plain doubles so sums stay exact until display. */
@Serializable
data class Macros(val kcal: Double = 0.0, val protein: Double = 0.0, val carbs: Double = 0.0, val fat: Double = 0.0) {
    operator fun plus(o: Macros) = Macros(kcal + o.kcal, protein + o.protein, carbs + o.carbs, fat + o.fat)
    operator fun minus(o: Macros) = Macros(kcal - o.kcal, protein - o.protein, carbs - o.carbs, fat - o.fat)
    operator fun times(k: Double) = Macros(kcal * k, protein * k, carbs * k, fat * k)

    /** This is "per 100 g": the macros of [grams] g. */
    fun forGrams(grams: Double) = this * (grams / 100.0)

    val isZero: Boolean get() = abs(kcal) < 0.5 && abs(protein) < 0.05 && abs(carbs) < 0.05 && abs(fat) < 0.05

    companion object {
        val ZERO = Macros()
        fun of(list: List<Double>) = Macros(list.getOrElse(0) { 0.0 }, list.getOrElse(1) { 0.0 }, list.getOrElse(2) { 0.0 }, list.getOrElse(3) { 0.0 })
    }
}

fun Iterable<Macros>.sum(): Macros = fold(Macros.ZERO) { a, b -> a + b }

/** Text in Arabic and English. Food names follow the interface: Arabic in the mixed and Arabic modes. */
interface Named {
    val ar: String
    val en: String
    fun name(language: AppLanguage): String = if (language == AppLanguage.ENGLISH) en else ar
}

@Serializable
data class FoodCategory(val id: String, override val ar: String, override val en: String) : Named

@Serializable
data class ServingUnit(val id: String, override val ar: String, override val en: String, val g: Double) : Named {
    companion object {
        /** Always offered next to the food's own units. */
        val GRAM = ServingUnit("g", "غرام", "Grams", 1.0)
    }
}

@Serializable
data class Food(
    val id: String,
    val cat: String,
    override val ar: String,
    override val en: String,
    val art: String? = null,
    val per100: List<Double>,
    val units: List<ServingUnit> = emptyList(),
    val defUnit: String = "g",
    val defQty: Double = 1.0,
    /** Add-on group offered after picking this food ("في إضافات؟"). */
    val addons: String? = null,
    /** Extra search words (other spellings, dialect names). */
    val aka: String? = null,
    val dish: Boolean = false,
) : Named {
    val macros100: Macros get() = Macros.of(per100)

    /** The food's units plus grams at the end (unless it already has a 1-g unit). */
    val allUnits: List<ServingUnit> get() = if (units.any { it.id == "g" }) units else units + ServingUnit.GRAM

    fun unit(id: String?): ServingUnit = allUnits.firstOrNull { it.id == id } ?: allUnits.first()

    val defaultUnit: ServingUnit get() = unit(defUnit)

    /** A gram amount reads better as 150 g than as 1.5 × 100 g. */
    fun defaultQty(unit: ServingUnit): Double = when {
        unit.id == defaultUnit.id -> defQty
        unit.g <= 1.0 -> (defaultUnit.g * defQty).roundToInt().toDouble().coerceAtLeast(1.0)
        else -> 1.0
    }

    fun macros(unit: ServingUnit, qty: Double): Macros = macros100.forGrams(unit.g * qty)

    val isCustom: Boolean get() = id.startsWith(CUSTOM_PREFIX)

    companion object {
        const val CUSTOM_PREFIX = "custom:"
    }
}

@Serializable
data class AddonUnit(override val ar: String, override val en: String, val g: Double) : Named

@Serializable
data class Addon(
    val id: String,
    override val ar: String,
    override val en: String,
    val art: String? = null,
    val per100: List<Double>,
    val unit: AddonUnit,
    val defQty: Double = 1.0,
) : Named {
    val macros100: Macros get() = Macros.of(per100)
    fun macros(qty: Double): Macros = macros100.forGrams(unit.g * qty)
}

@Serializable
data class FoodDb(
    val version: Int = 1,
    val categories: List<FoodCategory>,
    val foods: List<Food>,
    val addons: List<Addon>,
    val groups: Map<String, List<String>> = emptyMap(),
) {
    private val foodById by lazy { foods.associateBy { it.id } }
    private val addonById by lazy { addons.associateBy { it.id } }

    fun food(id: String): Food? = foodById[id]
    fun addon(id: String): Addon? = addonById[id]
    fun category(id: String): FoodCategory? = categories.firstOrNull { it.id == id }
    fun inCategory(id: String): List<Food> = foods.filter { it.cat == id }

    /** The add-ons offered for [food], in the order the group lists them. */
    fun addonsFor(food: Food): List<Addon> = food.addons?.let { groups[it] }.orEmpty().mapNotNull(::addon)

    companion object {
        private val json = Json { ignoreUnknownKeys = true; explicitNulls = false }
        fun parse(text: String): FoodDb = json.decodeFromString(serializer(), text)
    }
}
